create or replace function public.add_customer_equipment_atomic(p_customer_id uuid,p_equipment_type text,p_manufacturer text,p_model_number text,p_serial_number text,p_location text,p_installed_on date,p_warranty_expires_on date,p_last_service_on date,p_next_maintenance_on date,p_notes text)
returns uuid language plpgsql security definer set search_path=public,private,pg_temp as $$
declare a public.users%rowtype;c public.customers%rowtype;e uuid;et text:=btrim(coalesce(p_equipment_type,''));begin
select * into a from public.users where auth_user_id=auth.uid() and active=true limit 1;if a.id is null or a.role not in ('owner','manager','csr_dispatch','technician') then raise exception 'Not authorized';end if;if p_customer_id is null or et='' or length(et)>160 then raise exception 'Customer and valid equipment type are required';end if;select * into c from public.customers where id=p_customer_id for share;if not found then raise exception 'Customer not found';end if;
if p_installed_on is not null and p_installed_on>current_date+1 then raise exception 'Installed date cannot be in the future';end if;if p_last_service_on is not null and p_last_service_on>current_date+1 then raise exception 'Last service date cannot be in the future';end if;if p_warranty_expires_on is not null and p_installed_on is not null and p_warranty_expires_on<p_installed_on then raise exception 'Warranty expiration cannot precede installation';end if;if p_next_maintenance_on is not null and p_last_service_on is not null and p_next_maintenance_on<p_last_service_on then raise exception 'Next maintenance cannot precede last service';end if;if length(coalesce(p_notes,''))>5000 then raise exception 'Equipment notes are too long';end if;
insert into public.customer_equipment(customer_id,equipment_type,manufacturer,model_number,serial_number,location,installed_on,warranty_expires_on,last_service_on,next_maintenance_on,notes,created_by) values(p_customer_id,et,nullif(btrim(coalesce(p_manufacturer,'')),''),nullif(btrim(coalesce(p_model_number,'')),''),nullif(btrim(coalesce(p_serial_number,'')),''),nullif(btrim(coalesce(p_location,'')),''),p_installed_on,p_warranty_expires_on,p_last_service_on,p_next_maintenance_on,nullif(btrim(coalesce(p_notes,'')),''),a.id) returning id into e;
insert into public.audit_log(actor_user_id,action,entity_type,entity_id,after_data) values(a.id,'add_customer_equipment','customer_equipment',e::text,jsonb_build_object('customer_id',p_customer_id,'equipment_type',et,'manufacturer',nullif(btrim(coalesce(p_manufacturer,'')),''),'model_number',nullif(btrim(coalesce(p_model_number,'')),''),'serial_number',nullif(btrim(coalesce(p_serial_number,'')),''),'location',nullif(btrim(coalesce(p_location,'')),''),'installed_on',p_installed_on,'warranty_expires_on',p_warranty_expires_on,'last_service_on',p_last_service_on,'next_maintenance_on',p_next_maintenance_on,'status','active'));return e;end;$$;
revoke all on function public.add_customer_equipment_atomic(uuid,text,text,text,text,text,date,date,date,date,text) from public;grant execute on function public.add_customer_equipment_atomic(uuid,text,text,text,text,text,date,date,date,date,text) to authenticated;